import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import test from 'node:test';

import { buildProductHookBundle } from '../scripts/build-product-hook-bundle.mjs';

test('published product hook bundle is fresh, single-file, and source-auditable', async () => {
  const path = await buildProductHookBundle({ check: true });
  const source = readFileSync(path, 'utf8');
  assert.match(source, /^\/\/ Generated by scripts\/build-product-hook-bundle\.mjs\. Do not edit\./);
  assert.match(source, /runProductHookEntrypoint/);
  assert.doesNotMatch(source, /sourceMappingURL|node_modules\//);
  assert.doesNotMatch(source, /[ \t]+$/m);
});
